const ee = require('@google/earthengine');
const privateKey = require('./.earthsense-436113-b294c5f5c2dc.json');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const shanghai = ee.Geometry.Point([121.4737, 31.2304]); // Center of Shanghai
  const scale = 1113; // Sentinel-5P resolution is ~1113m

  const date_p1_start = '2020-02-10';
  const date_p1_end = '2020-02-25';

  const date_p2_start = '2020-04-20';
  const date_p2_end = '2020-05-12';

  const bandName = 'tropospheric_NO2_column_number_density';

  // Function to mask clouds and low quality data
  const maskS5P = function(image) {
    const qa = image.select('qa_value');
    // Filter on the 'qa_value' band.
    const maskedImage = image.updateMask(qa.gte(0.75)); // Keep pixels with QA > 0.75
    // Also mask out negative or zero NO2 values which are not physically meaningful.
    return maskedImage.updateMask(maskedImage.select(bandName).gt(0));
  };

  // 2. Data Acquisition & Check for Period 1
  let collection1 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(date_p1_start, date_p1_end)
    .filterBounds(shanghai)
    .map(maskS5P)
    .select(bandName);

  const size1 = await collection1.size().getInfo();
  if (size1 === 0) {
    console.log(`No images found for Period 1 (${date_p1_start} to ${date_p1_end}).`);
    console.log("C1");
    return;
  }

  // 2. Data Acquisition & Check for Period 2
  let collection2 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(date_p2_start, date_p2_end)
    .filterBounds(shanghai)
    .map(maskS5P)
    .select(bandName);

  const size2 = await collection2.size().getInfo();
  if (size2 === 0) {
    console.log(`No images found for Period 2 (${date_p2_start} to ${date_p2_end}).`);
    console.log("C1");
    return;
  }

  // Calculate mean images for each period
  const meanImage1 = collection1.mean();
  const meanImage2 = collection2.mean();

  // 3. Processing & Calculation for Period 1
  const stats1 = await meanImage1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: shanghai,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const meanNO2_1 = stats1 ? stats1[bandName] : null;
  const countNO2_1 = stats1 ? stats1[bandName + '_count'] : 0;

  if (countNO2_1 === 0 || meanNO2_1 === null) {
    console.log(`Period 1 Images: ${size1}. Valid pixels: ${countNO2_1}`);
    console.log("No valid pixels for Period 1 after masking/reduction.");
    console.log("C2");
    return;
  }

  // 3. Processing & Calculation for Period 2
  const stats2 = await meanImage2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: shanghai,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const meanNO2_2 = stats2 ? stats2[bandName] : null;
  const countNO2_2 = stats2 ? stats2[bandName + '_count'] : 0;

  if (countNO2_2 === 0 || meanNO2_2 === null) {
    console.log(`Period 2 Images: ${size2}. Valid pixels: ${countNO2_2}`);
    console.log("No valid pixels for Period 2 after masking/reduction.");
    console.log("C2");
    return;
  }

  // 5. Validation & Final Answer
  if (meanNO2_1 === null || isNaN(meanNO2_1) || meanNO2_2 === null || isNaN(meanNO2_2)) {
    console.log(`Period 1 mean: ${meanNO2_1}, Period 2 mean: ${meanNO2_2}`);
    console.log("C3"); // Calculation resulted in null or NaN
    return;
  }

  console.log(`Period 1 (${date_p1_start} to ${date_p1_end}): Images: ${size1}, Valid Pixels: ${countNO2_1}, Mean NO2: ${meanNO2_1.toExponential(2)} mol/m^2`);
  console.log(`Period 2 (${date_p2_start} to ${date_p2_end}): Images: ${size2}, Valid Pixels: ${countNO2_2}, Mean NO2: ${meanNO2_2.toExponential(2)} mol/m^2`);

  if (meanNO2_2 > meanNO2_1) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
